<?php
/*
 * common.php
 * 已改写以避免对 $GLOBALS 建立引用或一次性重写 $GLOBALS 导致的 PHP 8.1+ 错误
 */

// 保留常量定义逻辑，不使用引用
if (!defined('AAA__AA')) {
    define('AAA__AA', 'AAA_A__');
}

// 把 explode 的结果先保存到临时变量，再安全赋值到 $GLOBALS 指定键
$temp1 = explode("|Q|<|D", "H*|Q|<|D415F414141415F");
$GLOBALS['AAA__AA'] = is_array($temp1) ? $temp1 : [];

// 保留第二组常量和初始化，均使用临时变量并逐键写入
if (!defined('AA_AAAA')) {
    define('AA_AAAA', 'AAA____');
}

$temp2 = explode("|5|9|i", "H*|5|9|i41415F41415F41|5|9|i646566696E65|5|9|i41415F4141415F|5|9|i596D64|5|9|i485454505F484F5354|5|9|i646566656E6465725F74797065|5|9|i736C696465|5|9|i646566656E6465725F6B6579|5|9|i646566656E6465725F68617368|5|9|i6661696C|5|9|i7365635F646566656E64|5|9|i73756363657373|5|9|iE9AA8CE8AF81E5A4B1E8B4A5EFBC81|5|9|i7365635F646566656E645F74696D65|5|9|i436F6E74656E742D747970653A746578742F68746D6C3B636861727365743D7574662D38|5|9|iE6B58FE8A788E599A8E4B88DE694AFE68C81434F4F4B4945E68896E88085E4B88DE6ADA3E5B8B8E8AEBFE997AEEFBC81|5|9|");
$GLOBALS['AA_AAAA'] = is_array($temp2) ? $temp2 : [];

// 如果未来有其它需要批量写入的数组，请使用临时变量并逐键写入，示例：
// $vals = get_some_assoc_array();
// if (is_array($vals)) {
//     foreach ($vals as $k => $v) {
//         $GLOBALS[$k] = $v;
//     }
// }

// 注意：切勿使用类似 `$var =& $GLOBALS;` 或 `$GLOBALS = <expr>;` 的写法

?>
